insert into public.collections (id, name, short_name, tagline, description, featured_product_id, tint, accent, theme, sort_order) values
  ('mona-lisa', 'Mona Lisa’s Laundry', 'Mona Lisa', 'Classic art. Different attitude.', 'Tren Lisa, Mona Lifta and Mona Splita. Three familiar faces with a little extra attitude.', 'tren-lisa', '#132b47', '#d1c5ad', 'mona', 10),
  ('family-guy', 'Family Guy’s Laundry', 'Family Guy', 'Straight out of Quahog.', 'A little deadpan. A lot of character. Megatron Griffin and a Stewie who doesn’t need it to make sense.', 'megatron', '#132e4c', '#adcfff', 'family', 20),
  ('rick-and-morty', 'Rick and Morty’s Laundry', 'Rick & Morty', 'A different dimension.', 'Get Schwifty. A familiar duo, a portal, and a very different state of mind.', 'rick-and-morty', '#102d40', '#a4d5c3', 'rick', 30),
  ('spongebob', 'SpongeBob’s Laundry', 'SpongeBob', 'Below the surface.', 'Bikini Bottom, but make it a lifestyle. SpongeBob, Plankton, Larry, Mr. Krabs and a goofy goober or two.', 'spongebob', '#12334b', '#a2d9eb', 'sponge', 40),
  ('popeye', 'Popeye’s Laundry', 'Popeye', 'Every day is arm day.', 'A sailor with a strong point of view. Classic Popeye, in your rotation.', 'popeye', '#102a48', '#b8ccec', 'popeye', 50),
  ('bad-influence', 'Bad Influence Laundry', 'Bad Influence', 'A little less well behaved.', 'Big graphics. A sense of humor. A BUM leads this Laundry.', 'a-bum', '#202c49', '#c8c0e7', 'bad', 60),
  ('jujutsu-kaisen', 'Jujutsu Kaisen Laundry', 'Jujutsu Kaisen', 'Throughout heaven and earth.', 'Gojo, Sukuna and Toji. Three of the strongest, with the confidence to match.', 'nah-id-win', '#1d2147', '#c5b6f2', 'jjk', 70);
insert into public.products (id, collection_id, name, description, default_color, sort_order) values
  ('tren-lisa', 'mona-lisa', 'Tren Lisa', 'The Tren Lisa artwork on an oversized tee.', 'black', 10),
  ('mona-lifta', 'mona-lisa', 'Mona Lifta', 'Mona Lisa, with a little extra strength. The Mona Lifta design on an oversized tee.', 'black', 20),
  ('mona-splita', 'mona-lisa', 'Mona Splita', 'The Mona Splita design on an oversized tee.', 'black', 30),
  ('megatron', 'family-guy', 'Megatron Griffin', 'Megatron Griffin artwork on an oversized tee.', 'white', 40),
  ('stewie', 'family-guy', 'It Doesn’t Have to Make Sense', 'Stewie, flexing. It doesn’t have to make sense when you look like this.', 'black', 50),
  ('rick-and-morty', 'rick-and-morty', 'Get Schwifty', 'Rick and Morty surrounded by the colorful portal print.', 'black', 60),
  ('spongebob', 'spongebob', 'BOBLIFTSCRAZY', 'The Bikini Bottom Fitness artwork on an oversized tee.', 'white', 70),
  ('i-went-to-college', 'spongebob', 'I Went to College', 'Plankton, graduate. A tee for anyone who did the reading.', 'black', 80),
  ('livin-like-larry', 'spongebob', 'Livin’ Like Larry', 'Larry the Lobster, sun, surf and very big arms.', 'black', 90),
  ('i-like-money', 'spongebob', 'I Like Money', 'Mr. Krabs says it best. I like money.', 'white', 100),
  ('goofy-goober', 'spongebob', 'I’m a Goofy Goober', 'SpongeBob on guitar, full Goofy Goober rock mode.', 'black', 110),
  ('popeye', 'popeye', 'Everyday’s Arm Day', 'The Popeye arm-day artwork on an oversized tee.', 'white', 120),
  ('a-bum', 'bad-influence', 'A BUM', 'Will flex for protein. The A BUM design on an oversized tee.', 'white', 130),
  ('nah-id-win', 'jujutsu-kaisen', 'Nah, I’d Win', 'Gojo Satoru, unbothered. Nah, I’d win.', 'black', 140),
  ('know-your-place', 'jujutsu-kaisen', 'Know Your Place', 'Sukuna on his throne. Know your place, you fool.', 'black', 150),
  ('dont-work-for-free', 'jujutsu-kaisen', 'I Don’t Work for Free', 'Toji Fushiguro. I don’t work for free.', 'black', 160);
